import * as React from "react"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

type CuiButtonProps = React.ComponentProps<typeof Button>

const CuiButton = React.forwardRef<HTMLButtonElement, CuiButtonProps>(
    ({ className, ...props }, ref) => {
        return (
            <Button
                ref={ref}
                className={cn(
                    "active:scale-[0.97] transition-transform duration-150",
                    className
                )}
                {...props}
            />
        )
    }
)

CuiButton.displayName = "Button"

export { CuiButton as Button }

import * as React from "react"
import { Loader2Icon } from "lucide-react"
import { Button } from "./button"
import { buttonVariants } from "@/components/ui/button"

import type { VariantProps } from "class-variance-authority"

type LoadingButtonProps = React.ComponentProps<"button"> &
	VariantProps<typeof buttonVariants> & {
		asChild?: boolean
		isLoading?: boolean
	}

const LoadingButton = React.forwardRef<HTMLButtonElement, LoadingButtonProps>(
	({ isLoading, disabled, children, ...props }, ref) => {
		return (
			<Button
				ref={ref}
				disabled={disabled || isLoading}
				{...props}
			>
				{isLoading && (
					<Loader2Icon className="animate-spin" />
				)}
				{children}
			</Button>
		)
	}
)

LoadingButton.displayName = "LoadingButton"

export { LoadingButton }
